from pathlib import Path
import numpy as np
import pandas as pd
from _plot_config import HEADER
from _plot_style import METHOD_COLOR, METHOD_LABEL, footnote, plt, save
OUT=Path(".")
DEEPSEEK_BOUNDS=Path(__file__).parent.parent/"_data"/"deepseek_paired_bounds.csv"
CONFIG_ORDER = ['hold'] + [f'linear_g{g}' for g in ('050', '075', '100', '125', '150', '200')] + [f'damped_d{d}' for d in ('0125', '0250', '0500', '1000', '2000', '4000')] + [f'second_a{a}' for a in ('0050', '0100', '0200', '0250', '0500', '1000')]
F_S1 = HEADER + ' 数据 S1（v3 口径，误报类数值略高于修正口径），27 条轨迹，转角峰值均为 10°。'

def cm(cfg):
    return {'hold': 'hold', 'linear': 'linear', 'damped': 'damped_linear', 'second': 'bounded_second_order'}[cfg.split('_')[0]]

def fig01(s1):
    fig, ax = plt.subplots(figsize=(11, 4.2))
    data = [s1.loc[s1.config_id == c, 'geom_2.0_mean'].to_numpy() for c in CONFIG_ORDER]
    bp = ax.boxplot(data, patch_artist=True, widths=0.6, showfliers=False)
    for patch, c in zip(bp['boxes'], CONFIG_ORDER):
        patch.set_facecolor(METHOD_COLOR[cm(c)])
        patch.set_alpha(0.6)
    ax.set_xticks(range(1, len(CONFIG_ORDER) + 1), CONFIG_ORDER, rotation=45, ha='right')
    ax.set_ylabel('2 s 右缘端点误差均值 (m)')
    ax.set_title('预测误差随外推强度变化：适度外推最小，过强外推回升（与接触标签无关）')
    hs = [plt.Rectangle((0, 0), 1, 1, color=METHOD_COLOR[m], alpha=0.6) for m in METHOD_COLOR]
    ax.legend(hs, [METHOD_LABEL[m] for m in METHOD_COLOR], ncol=4, loc='upper left')
    ax.grid(axis='y', alpha=0.3)
    footnote(fig, F_S1 + ' 箱体为 27 条轨迹的分布。', y=-0.2)
    save(fig, OUT / 'fig01_端点误差_各配置.png')

def fig02(s1):
    d = s1[s1.method != 'hold']
    order = [c for c in CONFIG_ORDER if c != 'hold']
    g = d.groupby('config_id')['d_hold_right_pct']
    mean, lo, hi = (g.mean()[order], g.min()[order], g.max()[order])
    better = g.apply(lambda x: int((x < 0).sum()))[order]
    fig, ax = plt.subplots(figsize=(11, 4.2))
    x = np.arange(len(order))
    ax.bar(x, mean, color=[METHOD_COLOR[cm(c)] for c in order], alpha=0.7)
    ax.errorbar(x, mean, yerr=[mean - lo, hi - mean], fmt='none', ecolor='k', capsize=3, lw=0.8)
    for xi, b in enumerate(better):
        ax.text(xi, 0.32, f'{b}/27', ha='center', va='bottom', fontsize=7.5, color='k' if b == 27 else '#d62728')
    ax.set_ylim(lo.min() - 0.2, 0.6)
    ax.axhline(0, color='k', lw=0.8)
    ax.set_xticks(x, order, rotation=45, ha='right')
    ax.set_ylabel('RIGHT 不足率 − 保持 (pp)')
    ax.set_title('同一轨迹下与保持基线的配对差：数字为优于保持的轨迹数')
    ax.grid(axis='y', alpha=0.3)
    footnote(fig, F_S1 + ' 柱为均值，误差线为最小–最大；RIGHT 不足 = 窗口漏报或提前量 < 1 s。', y=-0.2)
    save(fig, OUT / 'fig02_配对迟报差_相对保持.png')

def fig03(s1):
    d = s1.groupby('config_id').agg(r=('right_pct', 'mean'), fp=('negative_fp_pct', 'mean')).loc[CONFIG_ORDER]
    lab = {'hold', 'damped_d0125', 'damped_d0250', 'damped_d1000', 'linear_g050', 'linear_g125', 'linear_g150', 'linear_g200', 'second_a0200', 'second_a1000'}
    fig, ax = plt.subplots(figsize=(7.5, 5))
    for cfg, row in d.iterrows():
        ax.scatter(row.fp, row.r, s=55, color=METHOD_COLOR[cm(cfg)], edgecolor='k', lw=0.5, zorder=3)
        if cfg in lab:
            ax.annotate(cfg, (row.fp, row.r), fontsize=7, xytext=(4, 4), textcoords='offset points')
    for m in METHOD_COLOR:
        sub = d[[cm(c) == m for c in d.index]]
        if len(sub) > 1:
            ax.plot(sub.fp, sub.r, color=METHOD_COLOR[m], lw=1, alpha=0.6)
    ax.set_xlabel('近场点误报率均值 (%)')
    ax.set_ylabel('RIGHT 不足率均值 (%)')
    ax.set_title('迟报与误报的权衡：没有同时最优的配置')
    hs = [plt.Line2D([], [], marker='o', ls='', color=METHOD_COLOR[m]) for m in METHOD_COLOR]
    ax.legend(hs, [METHOD_LABEL[m] for m in METHOD_COLOR], loc='upper right')
    ax.grid(alpha=0.3)
    footnote(fig, F_S1 + ' 绝对值仅作描述。')
    save(fig, OUT / 'fig03_迟报误报权衡.png')

def fig04(s1):
    d = s1[s1.config_id == 'damped_d1000']
    vmin = d['d_hold_right_pct'].min()
    fig, axes = plt.subplots(1, 3, figsize=(11, 3.6), sharey=True)
    names = {'symmetric': '对称动作', 'fast_entry': '较快入弯', 'fast_return': '较快回正'}
    for ax, tpl in zip(axes, names):
        p = d[d.template == tpl].pivot_table(index='v_B_mps', columns='base_rate_deg_s', values='d_hold_right_pct')
        im = ax.imshow(p.to_numpy(), cmap='Greens_r', vmin=vmin, vmax=0, origin='lower')
        ax.set_xticks(range(p.shape[1]), [f'{c:g}' for c in p.columns])
        ax.set_yticks(range(p.shape[0]), [f'{v:g}' for v in p.index])
        for i in range(p.shape[0]):
            for j in range(p.shape[1]):
                ax.text(j, i, f'{p.iat[i, j]:.2f}', ha='center', va='center', fontsize=9)
        ax.set_title(names[tpl])
        ax.set_xlabel('基准转角速率 r (°/s)')
    axes[0].set_ylabel('车速 v_B (m/s)')
    fig.colorbar(im, ax=axes, shrink=0.85, label='衰减线性 τ=1 s − 保持 (pp)')
    fig.suptitle('趋势外推的收益随车速和转向速率增大', x=0.43, y=1.02)
    footnote(fig, F_S1 + ' 越负表示相对保持基线迟报越少。')
    save(fig, OUT / 'fig04_驾驶因素_配对收益热图.png')

def fig05(s2, s4p):
    pre_label = {'raw': '原始输入', 'alpha_lp': '仅转角低通', 'age_hold': '按测量年龄前推（无延迟时同原始）'}
    pre_color = {'raw': '#1f77b4', 'alpha_lp': '#2ca02c', 'age_hold': '#ff7f0e'}
    style = {'raw': dict(ls='-', lw=3, alpha=0.5), 'alpha_lp': dict(ls='-'), 'age_hold': dict(ls='--')}
    fig, axes = plt.subplots(1, 3, figsize=(16, 4.2))
    noise = s2[s2.delay_ms == 0]
    for p in ('raw', 'alpha_lp', 'age_hold'):
        g = noise[noise.processor == p].groupby('noise_level')['negative_fp_pct']
        axes[0].plot(g.mean().index, g.mean(), marker='o', color=pre_color[p], label=pre_label[p], **style[p])
        if p != 'age_hold':
            axes[0].fill_between(g.mean().index, g.min(), g.max(), color=pre_color[p], alpha=0.12)
    axes[0].axhline(5, color='r', ls='--', lw=1, label='研究预算 5%')
    axes[0].set(xlabel='噪声倍率（α 0.15°、φ 0.25°、v 0.04 m/s 为 1 倍）', ylabel='近场点误报率 (%)', title='S2：误报主要由输入噪声决定（v3 口径）')
    axes[0].legend(fontsize=8)
    delay = s2[s2.noise_level == 0]
    for p in ('raw', 'alpha_lp', 'age_hold'):
        g = delay[delay.processor == p].groupby('delay_ms')['right_pct']
        axes[1].plot(g.mean().index, g.mean(), marker='o', color=pre_color[p], label=pre_label[p].split('（')[0])
    axes[1].set(xlabel='纯延迟 (ms)', ylabel='RIGHT 不足率均值 (%)', title='S2：延迟主要推高迟报')
    axes[1].legend(fontsize=8)
    order = ['raw', 'phi_ekf_q100', 'phi_ekf_q025', 'phi_ekf_q025_alphaLP050']
    g = s4p.groupby('processor').agg(fp=('negative_fp_pct', 'mean'), miss=('right_miss_rate', 'mean'), anymiss=('any_window_miss', 'sum')).reindex(order)
    x = np.arange(len(order))
    axes[2].bar(x - 0.2, g.fp, 0.4, color='#4c72b0', label='近场点误报率均值 (%)')
    ax2 = axes[2].twinx()
    ax2.bar(x + 0.2, g.miss, 0.4, color='#d62728', label='窗口漏报率均值 (%)')
    for xi, n in enumerate(g.anymiss):
        ax2.text(xi + 0.2, g.miss.iloc[xi], f'{int(n)} 行', ha='center', va='bottom', fontsize=7, color='#d62728')
    axes[2].set_xticks(x, ['raw', 'φEKF q100', 'φEKF q025', 'φEKF q025\n+α低通'], fontsize=8)
    axes[2].set(ylabel='近场点误报率均值 (%)', title='S4：状态估计降误报，但带来漏报（修正口径）')
    ax2.set_ylabel('窗口漏报率均值 (%)', color='#d62728')
    h1, l1 = axes[2].get_legend_handles_labels()
    h2, l2 = ax2.get_legend_handles_labels()
    axes[2].legend(h1 + h2, l1 + l2, fontsize=7, loc='upper center')
    ax2.set_ylim(0, g.miss.max() * 1.35)
    for ax in axes:
        ax.grid(alpha=0.3)
    footnote(fig, HEADER + ' S2：6 条轨迹 × 3 方法，噪声各 3 个种子，阴影为最小–最大；S4：同 6 条轨迹 × 3 方法 × 8 条件；红字为出现窗口漏报的评分行数（不是独立事故数）。')
    save(fig, OUT / 'fig05_噪声延迟与状态估计.png')

def fig06(d3):
    d = d3[(d3.partition == 'development_v2_n70000') & (d3.method != 'hold')]
    metrics = [('d_post_right_pct', 'RIGHT 不足率变化 (pp)', 'RdYlGn_r'), ('d_post_right_miss_rate', '窗口漏报率变化 (pp)', 'RdYlGn_r'), ('d_post_negative_fp_pct', '近场点误报率变化 (pp)', 'RdYlGn_r'), ('d_post_common_2s_fpr_pct', '共同 2 s 逐帧误报率变化 (pp)', 'RdYlGn_r')]
    fig, axes = plt.subplots(2, len(metrics), figsize=(4.2 * len(metrics), 6.5))
    for j, (col, name, cmap) in enumerate(metrics):
        piv_all = d.groupby(['EXIT_W_s', 'margin_m', 'confirmation_s'])[col].mean()
        lim = np.nanmax(np.abs(piv_all.to_numpy()))
        for i, W in enumerate((2.0, 3.0)):
            p = piv_all.loc[W].unstack('confirmation_s').fillna(0.0)
            im = axes[i, j].imshow(p.to_numpy(), cmap=cmap, vmin=-lim, vmax=lim, origin='lower', aspect='auto')
            axes[i, j].set_xticks(range(p.shape[1]), [f'{c:g} s' for c in p.columns])
            axes[i, j].set_yticks(range(p.shape[0]), [f'{m:g} m' for m in p.index])
            for a in range(p.shape[0]):
                for b in range(p.shape[1]):
                    is_ref = W == 2.0 and p.index[a] == 0 and (p.columns[b] == 0)
                    axes[i, j].text(b, a, '参照' if is_ref else f'{p.iat[a, b]:+.2f}', ha='center', va='center', fontsize=9)
            if i == 0:
                axes[i, j].set_title(name, fontsize=9)
            if j == 0:
                axes[i, j].set_ylabel(f'出弯窗口 W={W:g} s\n空间膨胀')
            if i == 1:
                axes[i, j].set_xlabel('确认时间')
        fig.colorbar(im, ax=axes[:, j], shrink=0.8)
    fig.suptitle('S3：后处理三因素相对“无后处理”的平均变化（绿色更好、红色更差）', y=1.0)
    footnote(fig, HEADER + ' 数据 S3 修正口径，27 条开发轨迹 × 2 方法 × 8 观测条件求均值；W=2 s、0 m、0 s 为参照（恒为 0）。')
    save(fig, OUT / 'fig06_后处理三因素交互.png')

def fig07(d5):
    fig, axes = plt.subplots(1, 3, figsize=(15, 4.2))
    variants = {'W2_m0_c0': ('无后处理', '-'), 'W2_m0.05_c0': ('膨胀 0.05 m', '--'), 'W2_m0_c0.1': ('确认 0.1 s', ':')}
    for ax, (col, name) in zip(axes, [('right_pct', 'RIGHT 不足率均值 (%)'), ('right_miss_rate', '窗口漏报率均值 (%)'), ('negative_fp_pct', '近场点误报率均值 (%)')]):
        for m, color in (('linear', METHOD_COLOR['linear']), ('damped_linear', METHOD_COLOR['damped_linear'])):
            for v, (vn, ls) in variants.items():
                s = d5[(d5.method == m) & (d5.variant == v)].groupby('gain_eff')[col].mean()
                ax.plot(s.index, s.values, marker='o', ls=ls, color=color, label=f'{METHOD_LABEL[m]} · {vn}')
        for v, (vn, ls) in variants.items():
            h = d5[(d5.method == 'hold') & (d5.variant == v)][col].mean()
            ax.axhline(h, color=METHOD_COLOR['hold'], ls=ls, lw=1, label=f'保持 · {vn}')
        ax.set(xlabel='趋势增益 g', ylabel=name)
        ax.grid(alpha=0.3)
    axes[0].legend(fontsize=6.5, ncol=2)
    fig.suptitle('S4 联合精化：趋势增益细档与后处理的效果')
    footnote(fig, HEADER + ' 数据 S4 修正口径，12 条选择轨迹 × 8 观测条件求均值；线性 τ 参数为 0.5、衰减线性 τ=1 s。')
    save(fig, OUT / 'fig07_趋势增益曲线.png')

def fig09():
    d = pd.read_csv(DEEPSEEK_BOUNDS)
    lh = d['paired_pct'].str.split('\\.\\.', regex=True, expand=True).astype(float)
    d['lo'], d['hi'] = (lh[0], lh[1])
    d = d.iloc[::-1].reset_index(drop=True)
    name = {'damped_linear_g1000_d1000': '衰减线性 τ=1 s', 'linear_g0500_d0500': '线性 g=0.5'}
    fig, ax = plt.subplots(figsize=(8, 6))
    for i, r in d.iterrows():
        color = '#2ca02c' if r.hi < 0 else '#7f7f7f'
        ax.plot([r.lo, r.hi], [i, i], color=color, lw=4, solid_capstyle='butt')
        ax.plot([r.lo, r.hi], [i, i], '|', color='k', ms=8)
        if r.hi - r.lo < 1e-09:
            ax.plot([r.lo], [i], 'o', color=color, ms=5)
            ax.annotate('恰为 0', (r.lo, i), xytext=(6, -3), textcoords='offset points', fontsize=7)
    ax.set_yticks(range(len(d)), [f'{r.condition} · {name.get(r.method_A, r.method_A)}' for _, r in d.iterrows()], fontsize=8)
    ax.axvline(0, color='k', lw=0.8)
    ax.set_xlabel('RIGHT 不足率配对差 A − 保持 (pp)，区间为标签不确定性下的上下界')
    ax.set_title('标签不确定性对配对结论的影响\n绿色：区间全在 0 以下（方向不受标签影响）；灰色：跨 0')
    ax.grid(axis='x', alpha=0.3)
    footnote(fig, '数据：DeepSeek 正向区间评分，v2_r2_symmetric 一条轨迹、70000 点、1854 帧，独立核验尚未进行。')
    save(fig, OUT / 'fig12_标签区间旁证.png')
